<?php require_once __DIR__ . '/../src/partials.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pid=(int)$_POST['product_id'];$qty=(int)$_POST['quantity'];try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT current_stock,active FROM products WHERE id=? FOR UPDATE');$s->execute([$pid]);$row=$s->fetch();$stock=$row['current_stock']??false;if($stock===false||!filter_var($row['active']??false,FILTER_VALIDATE_BOOLEAN)||$qty<1||$stock<$qty)throw new Exception($stock===false?'ไม่พบสินค้า':'สินค้านี้ถูกปิดใช้งานหรือมีจำนวนไม่เพียงพอสำหรับการเบิก');$s=$pdo->prepare("INSERT INTO stock_movements(product_id,movement_type,quantity,reference_no,note,user_id) VALUES(?,'OUT',?,?,?,?)");$s->execute([$pid,$qty,trim($_POST['reference_no']),trim($_POST['note']),$_SESSION['user']['id']]);$s=$pdo->prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?');$s->execute([$qty,$pid]);$pdo->commit();flash('success','เบิกสินค้าออกจากสต๊อกแล้ว');header('Location:/stock_out.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getMessage());}}$products=db()->query('SELECT * FROM products WHERE active=TRUE ORDER BY name')->fetchAll();page_start('สินค้าออก');?><div class="card form-card"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>สินค้า</label><select name="product_id" required><option value="">-- เลือกสินค้า --</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['code'].' - '.$p['name'].' (คงเหลือ '.$p['current_stock'].')')?></option><?php endforeach;?></select><div class="form-grid"><div><label>จำนวน</label><input type="number" name="quantity" min="1" required></div><div><label>เลขที่อ้างอิง</label><input name="reference_no"></div></div><label>หมายเหตุ</label><textarea name="note"></textarea><button class="primary">บันทึกสินค้าออก</button></form></div><?php page_end();
